<script setup>
import { reactive, ref } from 'vue'
const props=defineProps({ party:Object }); const emit = defineEmits(['created'])
const form = reactive({ title:'Поставка товаров', description:'', amount:'', buyer_inn:'7707083893', seller_inn:props.party?.inn||'7703451281' }); const error=ref(''); const busy=ref(false)
async function submit(){if(!form.title||!form.description||Number(form.amount)<=0||!/^\d{10}(\d{2})?$/.test(form.buyer_inn)||!/^\d{10}(\d{2})?$/.test(form.seller_inn)){error.value='Заполните все поля: ИНН состоит из 10 или 12 цифр, сумма — больше нуля.';return}busy.value=true;error.value='';try{const { dealsApi }=await import('../services/api');emit('created',await dealsApi.createEscrow({...form,amount:Number(form.amount)}))}catch(e){error.value=e.message}finally{busy.value=false}}
</script>
<template><section class="mx-auto grid max-w-[1080px] gap-10 px-5 py-10 md:grid-cols-[1fr_390px] md:px-0"><div><p class="text-xs text-[#9c9c9c]">Гарант-сделка</p><h1 class="mt-4 max-w-[580px] text-4xl font-semibold leading-tight md:text-5xl">Деньги у Smart Retail, пока обе стороны не подтвердят поставку.</h1><p class="mt-6 max-w-[580px] leading-7 text-[#a0a0a0]">Комиссия 1,2% считается от суммы. Открывая сделку, стороны соглашаются с офертой гаранта. Спор разбирается до выплаты.</p><div class="mt-10 rounded-lg border border-[#2b2b2b] bg-[#101010] p-6"><p class="text-xs text-[#999]">Расчёт</p><div class="mt-5 flex justify-between border-b border-[#2b2b2b] pb-4 text-sm"><span>ООО «Северная лавка»</span><span>Получатель</span></div><p class="mt-5 text-sm text-[#9c9c9c]">Деньги возвращаются покупателю, если поставка не подтверждена до 10 октября.</p></div></div><form class="rounded-lg border border-[#2b2b2b] bg-[#101010] p-6" @submit.prevent="submit"><h2 class="text-xl font-semibold">Открыть сделку</h2><div class="mt-6 space-y-3"><input v-model="form.title" class="field" placeholder="Название сделки"><textarea v-model="form.description" class="field min-h-24" placeholder="Описание"></textarea><input v-model="form.amount" class="field" type="number" placeholder="Сумма, ₽"><input v-model="form.buyer_inn" class="field" placeholder="ИНН покупателя"><input v-model="form.seller_inn" class="field" placeholder="ИНН получателя"></div><button class="mt-5 w-full rounded-md bg-[#d4ff34] py-3 text-sm font-semibold text-black" :disabled="busy">{{busy?'Открываем…':'Заморозить средства'}}</button><p v-if="error" class="mt-3 text-sm text-red-400">{{error}}</p></form></section></template>
